    });

    return Border(background: Bind.From(() => UiTheme.T.Background), padding: new Thickness(20))[
        VStack(10)[
            Heading("NodeGraphView — 配線"),
            Muted("ポートからドラッグ → 進行中ワイヤ (緑=可/赤=不可) → 互換ポートで接続。辺クリック選択 → Delete で切断。"),
